import{_ as a,c as o,o as t,ag as n}from"./chunks/framework.B3RpK1bM.js";const b=JSON.parse('{"title":"Code Style Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/code-writing-specifications.md","filePath":"en_EN/code-writing-specifications.md","lastUpdated":1769658044000}'),s={name:"en_EN/code-writing-specifications.md"};function l(i,e,d,c,r,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="code-style-guidelines" tabindex="-1">Code Style Guidelines <a class="header-anchor" href="#code-style-guidelines" aria-label="Permalink to &quot;Code Style Guidelines&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><h2 id="godot" tabindex="-1">Godot <a class="header-anchor" href="#godot" aria-label="Permalink to &quot;Godot&quot;">​</a></h2><h3 id="scene" tabindex="-1">Scene <a class="header-anchor" href="#scene" aria-label="Permalink to &quot;Scene&quot;">​</a></h3><p>Define the <strong>showing scene</strong> and <strong>function scene</strong> concepts.</p><h4 id="scene-baseline-rules" tabindex="-1">Scene Baseline Rules <a class="header-anchor" href="#scene-baseline-rules" aria-label="Permalink to &quot;Scene Baseline Rules&quot;">​</a></h4><ul><li>Scenes should be stored in the <code>./scene</code> folder under the root node name.</li><li>The naming convention for scenes should follow camel case.</li><li>The root node of the scene should match its name.</li></ul><h4 id="showing-scene" tabindex="-1">Showing Scene <a class="header-anchor" href="#showing-scene" aria-label="Permalink to &quot;Showing Scene&quot;">​</a></h4><p><strong>Showing scene</strong> refers to scenes that can be directly navigated to, such as <code>main.tscn</code>, <code>game.tscn</code>, or <code>end.tscn</code>. The basic rules for showing scenes are as follows:</p><ul><li>Only the root node manages basic control operations.</li></ul><h4 id="function-scene" tabindex="-1">Function Scene <a class="header-anchor" href="#function-scene" aria-label="Permalink to &quot;Function Scene&quot;">​</a></h4><p><strong>Function scene</strong> refers to scenes where certain functions are implemented by adding them. For example, <code>bottom.tscn</code> or <code>font.tscn</code>. The basic rules for function scenes are as follows:</p><ul><li>One function scene implements one business operation.</li><li>A function scene should not directly inherit from the themes within the <code>./theme</code> directory; instead, it should inherit from the corresponding showing scene.</li></ul><h3 id="node" tabindex="-1">Node <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node&quot;">​</a></h3><h4 id="node-baseline-rules" tabindex="-1">Node Baseline Rules <a class="header-anchor" href="#node-baseline-rules" aria-label="Permalink to &quot;Node Baseline Rules&quot;">​</a></h4><ul><li>Nodes should use camel case for their names.</li></ul><h2 id="c" tabindex="-1">C# <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C#&quot;">​</a></h2><p>C# files should be stored in the <code>./ezgal/csharp</code> folder.</p><h3 id="c-baseline-rules" tabindex="-1">C# Baseline Rules <a class="header-anchor" href="#c-baseline-rules" aria-label="Permalink to &quot;C# Baseline Rules&quot;">​</a></h3><ul><li>File names should correspond to the inherited nodes using camel case.</li><li>Variable naming conventions are as follows:</li></ul><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td>Public variables (global)</td><td>Use uppercase camel case (<code>CamelCase</code>).</td></tr><tr><td>Private variables (global)</td><td>Use underscore followed by lowercase camel case (<code>_camelCase</code>).</td></tr><tr><td>Internal variables (functions)</td><td>Use lowercase camel case (<code>camelCase</code>).</td></tr><tr><td>When accessing a variable, ensure that the variable name matches the name of the node being accessed.</td><td></td></tr><tr><td>If the variable corresponds to a single node, add <code>_node</code> at the end.</td><td></td></tr><tr><td>If the variable corresponds to a scene, add <code>_scene</code> at the end.</td><td></td></tr><tr><td>If the variable corresponds to a path, add <code>_path</code> at the end.</td><td></td></tr></tbody></table><ul><li>Functions should use camel case.</li><li>Complex functions should be succinctly described using <code>&lt;summary&gt; &lt;/summary&gt;</code> tags, with English-Chinese-Japanese order recommended for language.</li></ul><h3 id="global-files" tabindex="-1">Global Files <a class="header-anchor" href="#global-files" aria-label="Permalink to &quot;Global Files&quot;">​</a></h3><p>The current C# global file includes <code>FlowData.cs</code>, <code>Global.cs</code>, and <code>Tools.cs</code>.</p><h5 id="flowdata" tabindex="-1">FlowData <a class="header-anchor" href="#flowdata" aria-label="Permalink to &quot;FlowData&quot;">​</a></h5><p><code>FlowData.cs</code> is a core definition file for deep</p>',26)])])}const f=a(s,[["render",l]]);export{b as __pageData,f as default};
